
import { navigate } from "gatsby";
import React, { useEffect, useState } from "react";
import type { UserRole, UserStatus } from "../types";
import {
  createUser,
  getUserById,
  updateUser,
} from "../../../sessionServices/users/usersService";
import { writeAuditLog } from "../../../sessionServices/audit/auditLogsService";
import { useAuth } from "../../auth/AuthContext";

interface Props {
  uid?: string;
}

const ROLES: UserRole[] = ["admin", "customer"];
const STATUSES: UserStatus[] = ["active", "inactive", "blocked"];

const EMPTY_FORM = {
  fullName: "",
  email: "",
  password: "",
  phoneNumber: "",
  role: "customer" as UserRole,
  status: "active" as UserStatus,
  language: "",
};

export function UserForm({ uid }: Props) {
  const { user: currentUser } = useAuth();
  const isEditing = Boolean(uid);

  const [form, setForm] = useState(EMPTY_FORM);
  const [loading, setLoading] = useState(isEditing);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (!uid) return;
    getUserById(uid).then((profile) => {
      if (!profile) return;
      setForm({
        fullName: profile.fullName,
        email: profile.email,
        password: "",
        phoneNumber: profile.phoneNumber ?? "",
        role: profile.role,
        status: profile.status,
        language: profile.language ?? "",
      });
      setLoading(false);
    });
  }, [uid]);

  function set(field: keyof typeof EMPTY_FORM, value: string) {
    setForm((prev) => ({ ...prev, [field]: value }));
  }

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (!currentUser) return;
    setError(null);
    setSaving(true);

    try {
      if (isEditing && uid) {
        await updateUser(uid, {
          fullName: form.fullName,
          phoneNumber: form.phoneNumber || undefined,
          role: form.role,
          status: form.status,
          language: form.language || undefined,
          updatedBy: currentUser.uid,
        });
        await writeAuditLog({
          entityType: "user",
          entityId: uid,
          action: "update",
          after: { fullName: form.fullName, role: form.role, status: form.status },
          performedBy: currentUser.uid,
        });
      } else {
        // Use a secondary app instance so the admin session is not replaced
        const { firebaseConfig } = await import("../../../lib/firebase");
        const { initializeApp, deleteApp } = await import("firebase/app");
        const { getAuth, createUserWithEmailAndPassword: createUser2 } = await import("firebase/auth");

        const secondaryApp = initializeApp(firebaseConfig, "secondary-" + Date.now());
        const secondaryAuth = getAuth(secondaryApp);
        try {
          const credential = await createUser2(secondaryAuth, form.email, form.password);
          await createUser({
            uid: credential.user.uid,
            fullName: form.fullName,
            email: form.email,
            phoneNumber: form.phoneNumber || undefined,
            role: form.role,
            language: form.language || undefined,
            createdBy: currentUser.uid,
          });
          await writeAuditLog({
            entityType: "user",
            entityId: credential.user.uid,
            action: "create",
            after: { fullName: form.fullName, email: form.email, role: form.role },
            performedBy: currentUser.uid,
          });
        } finally {
          await deleteApp(secondaryApp);
        }
      }
      navigate("/admin/users");
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : "An error occurred.";
      setError(message);
    } finally {
      setSaving(false);
    }
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center py-16">
        <div className="h-6 w-6 animate-spin rounded-full border-4 border-gray-300 border-t-gray-800" />
      </div>
    );
  }

  return (
    <form onSubmit={handleSubmit} className="max-w-lg space-y-5">
      <Field label="Full name" required>
        <input
          type="text"
          required
          value={form.fullName}
          onChange={(e) => set("fullName", e.target.value)}
          className={inputClass}
        />
      </Field>

      {!isEditing && (
        <>
          <Field label="Email" required>
            <input
              type="email"
              required
              value={form.email}
              onChange={(e) => set("email", e.target.value)}
              className={inputClass}
            />
          </Field>
          <Field label="Password" required>
            <input
              type="password"
              required
              minLength={8}
              value={form.password}
              onChange={(e) => set("password", e.target.value)}
              className={inputClass}
            />
          </Field>
        </>
      )}

      <Field label="Phone">
        <input
          type="tel"
          value={form.phoneNumber}
          onChange={(e) => set("phoneNumber", e.target.value)}
          className={inputClass}
        />
      </Field>

      <Field label="Language">
        <input
          type="text"
          placeholder="e.g. en, fr, es"
          value={form.language}
          onChange={(e) => set("language", e.target.value)}
          className={inputClass}
        />
      </Field>

      <Field label="Role" required>
        <select
          value={form.role}
          onChange={(e) => set("role", e.target.value as UserRole)}
          className={inputClass}
        >
          {ROLES.map((r) => (
            <option key={r} value={r}>
              {r}
            </option>
          ))}
        </select>
      </Field>

      {isEditing && (
        <Field label="Status" required>
          <select
            value={form.status}
            onChange={(e) => set("status", e.target.value as UserStatus)}
            className={inputClass}
          >
            {STATUSES.map((s) => (
              <option key={s} value={s}>
                {s}
              </option>
            ))}
          </select>
        </Field>
      )}

      {error && (
        <p className="rounded-lg bg-red-50 px-3 py-2 text-sm text-red-600">
          {error}
        </p>
      )}

      <div className="flex gap-3 pt-2">
        <button
          type="submit"
          disabled={saving}
          className="rounded-lg bg-gray-900 px-5 py-2 text-sm font-medium text-white transition hover:bg-gray-700 disabled:opacity-60"
        >
          {saving ? "Saving..." : isEditing ? "Save changes" : "Create user"}
        </button>
        <button
          type="button"
          onClick={() => navigate("/admin/users")}
          className="rounded-lg border border-gray-300 px-5 py-2 text-sm font-medium text-gray-700 transition hover:bg-gray-100"
        >
          Cancel
        </button>
      </div>
    </form>
  );
}

function Field({
  label,
  required,
  children,
}: {
  label: string;
  required?: boolean;
  children: React.ReactNode;
}) {
  return (
    <div>
      <label className="mb-1 block text-sm font-medium text-gray-700">
        {label}
        {required && <span className="ml-0.5 text-red-500">*</span>}
      </label>
      {children}
    </div>
  );
}

const inputClass =
  "block w-full rounded-lg border border-gray-300 px-3 py-2 text-sm text-gray-900 focus:border-gray-800 focus:outline-none focus:ring-1 focus:ring-gray-800";
